import os


def _walk_files(base):
    results = []
    if not os.path.isdir(base):
        return results
    for dirpath, dirnames, filenames in os.walk(base):
        for fn in filenames:
            if fn.endswith('.jsonl'):
                results.append(os.path.join(dirpath, fn))
    return results


paths = sorted(_walk_files('tests/corpus') + _walk_files('src/lypning/assets/corpus'))

for p in paths:
    try:
        with open(p, encoding='utf-8') as f:
            for ln in f:
                ln = ln.strip()
                if not ln:
                    continue
                try:
                    o = json.loads(ln)
                except ValueError:
                    continue
                s = o.get('program')
                if isinstance(s, str) and len(s) > m:
                    m = len(s)
                    k = (p, o.get('id'))
