def safe_repr(s):
    # Convert string to its repr-equivalent without using repr() on the string itself
    # We need to produce a Python literal that, when passed to int(), equals s
    # and produces byte-identical output when printed.

    # We'll manually build the repr of the string:
    # - If it contains no special chars, just quote it with single or double quotes
    # - Handle backslashes, quotes, newlines, tabs, etc.

    result = []
    for c in s:
        cp = ord(c)
        if c == '\\':
            result.append('\\\\')
        elif c == '\n':
            result.append('\\n')
        elif c == '\t':
            result.append('\\t')
        elif c == '\r':
            result.append('\\r')
        elif c == "'":
