import os, sys

def wrap_line(line, width):
    # break_long_words=False: do not split words longer than width;
    # they simply occupy their own line.
    # break_on_hyphens=False: hyphen is just another character (word char).
    words = line.split(' ')
    if not words:
        return ['']
    lines = []
    cur = ''
    for word in words:
        if word == '':
