import os, sys

def wrap_line(line, width):
    # break_long_words=False: do not split words longer than width;
    # they simply occupy their own line.
    # break_on_hyphens=False: hyphen is just another character (word char).
    words = line.split(' ')
    if not words:
        return ['']
    lines = []
    cur = ''
    for word in words:
        if word == '':
            new_candidate = cur + ' ' + word if cur else word
        else:
            new_candidate = cur + ' ' + word if cur else word
        if len(new_candidate) <= width or not cur:
            cur = new_candidate
        elif len(word) > width:
            # current line already has content (cur non-empty), and this word alone exceeds width
            # since break_long_words=False, emit the current line, then the word on its own line(s)
            # but actually break_long_words=False means we don't break it, so it goes on its own line
            # even if longer than width
            lines.append(cur)
            cur = word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    elif lines is not None and len(lines) == 0:
        lines = ['']
    return lines

