        path_and_query = rest[p_idx:]
else:
    # Check for path before query
    slash_idx = rest.find("/")
    if slash_idx == -1 or q_idx < slash_idx:
        netloc = rest[:q_idx]
        path_and_query = rest[q_idx:]
    else:
        netloc = rest[:slash_idx]
        path_and_query = rest[slash_idx:]

# Split path and query
if "?" in path_and_query:
    q_pos = path_and_query.index("?")
    path = path_and_query[:q_pos]
    query = path_and_query[q_pos + 1:]
