def parse_qs(query_string):
    result = {}
    if not query_string:
        return result
    pairs = query_string.split("&")
    for pair in pairs:
        if not pair:
            continue
        if "=" in pair:
            k, v = pair.split("=", 1)
        else:
            k, v = pair, ""
        # URL decode minimal (no imports allowed for urllib, so handle basic cases)
        k = k.replace("+", " ")
        v = v.replace("+", " ")
        # Handle percent encoding
        def percent_decode(s):
            out = []
            i = 0
            while i < len(s):
                if s[i] == '%' and i + 2 < len(s):
                    hex_digits = s[i+1:i+3]
                    try:
                        byte_val = int(hex_digits, 16)
                        out.append(chr(byte_val))
                        i += 3
                    except ValueError:
                        out.append(s[i])
                        i += 1
                else:
                    out.append(s[i])
                    i += 1
            return "".join(out)
        k = percent_decode(k)
        v = percent_decode(v)
        if k in result:
            result[k].append(v)
        else:
            result[k] = [v]
    return result

