import re, os

def read_lines(path):
    with open(path, 'r', encoding='utf-8') as f:
        return f.read().splitlines()

def glob_rs(directory):
    if not os.path.isdir(directory):
        return []
    files = [name for name in sorted(os.listdir(directory)) if name.endswith('.rs')]
    return [os.path.join(directory, name) for name in files]

RUST = "src/lypning/assets/rust/src"
D = re.compile(r"or_else\(\|\|\s*kw(get|val)\(")
off = []
for p in glob_rs(RUST):
    lines = read_lines(p)
    base_name = os.path.basename(p)
    for n, line in enumerate(lines, 1):
        if D.search(line) and not line.lstrip().startswith("///"):
            off.append("%s:%d: %s" % (base_name, n, line.strip()))
print("offenders:", off or "NONE")
b = sum(len(re.findall(r"args::bind\(", '\n'.join(read_lines(p)))) for p in glob_rs(RUST))
print("args::bind call sites:", b)
